// SPDX-License-Identifier: MIT
pragma solidity ^0.8.17;

import { Math } from '@openzeppelin/contracts/utils/math/Math.sol';

/**
 * @title SharesMathLib
 * @notice Library for handling share-related calculations in the vault
 * @dev All functions use consistent rounding and scaling to maintain precision
 */
library SharesMathLib {
    using Math for uint256;

    /**
     * @notice Converts assets to shares, rounding down
     * @dev For first deposit (totalShares = 0), returns scaled assets
     * @param assets Amount of assets to convert
     * @param totalAssets Total amount of assets in vault
     * @param totalShares Total amount of shares in circulation
     * @return Amount of shares
     */
    function toSharesDown(uint256 assets, uint256 totalAssets, uint256 totalShares) internal pure returns (uint256) {
        if (totalShares == 0) {
            return assets;
        }
        return assets.mulDiv(totalShares, totalAssets, Math.Rounding.Floor);
    }

    /**
     * @notice Converts shares to assets, rounding down
     * @param shares Amount of shares to convert
     * @param totalShares Total amount of shares in circulation
     * @param totalAssets Total amount of assets in vault
     * @return Amount of assets
     */
    function toAssetsDown(uint256 shares, uint256 totalShares, uint256 totalAssets) internal pure returns (uint256) {
        if (totalShares == 0) {
            return 0;
        }
        return shares.mulDiv(totalAssets, totalShares, Math.Rounding.Floor);
    }

    /**
     * @notice Converts assets to shares, rounding up
     * @dev For first deposit (totalShares = 0), returns scaled assets
     * @param assets Amount of assets to convert
     * @param totalAssets Total amount of assets in vault
     * @param totalShares Total amount of shares in circulation
     * @return Amount of shares
     */
    function toSharesUp(uint256 assets, uint256 totalAssets, uint256 totalShares) internal pure returns (uint256) {
        if (totalShares == 0) {
            return assets;
        }
        return assets.mulDiv(totalShares, totalAssets, Math.Rounding.Ceil);
    }

    /**
     * @notice Converts shares to assets, rounding up
     * @param shares Amount of shares to convert
     * @param totalShares Total amount of shares in circulation
     * @param totalAssets Total amount of assets in vault
     * @return Amount of assets
     */
    function toAssetsUp(uint256 shares, uint256 totalShares, uint256 totalAssets) internal pure returns (uint256) {
        if (totalShares == 0) {
            return 0;
        }
        return shares.mulDiv(totalAssets, totalShares, Math.Rounding.Ceil);
    }

    /**
     * @notice Calculates withdrawal amount based on shares, rounding down
     * @param assetBalance Current balance of assets
     * @param shares Amount of shares to withdraw
     * @param totalShares Total amount of shares in circulation
     * @return Amount of assets to withdraw
     */
    function toWithdrawAmountDown(
        uint256 assetBalance,
        uint256 shares,
        uint256 totalShares
    ) internal pure returns (uint256) {
        if (totalShares == 0) {
            return 0;
        }
        return assetBalance.mulDiv(shares, totalShares, Math.Rounding.Floor);
    }

    /**
     * @notice Calculates withdrawal amount based on shares, rounding up
     * @param assetBalance Current balance of assets
     * @param shares Amount of shares to withdraw
     * @param totalShares Total amount of shares in circulation
     * @return Amount of assets to withdraw
     */
    function toWithdrawAmountUp(
        uint256 assetBalance,
        uint256 shares,
        uint256 totalShares
    ) internal pure returns (uint256) {
        if (totalShares == 0) {
            return 0;
        }
        return assetBalance.mulDiv(shares, totalShares, Math.Rounding.Ceil);
    }
}

contracts/studio/prov1/modules/DepositMo.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.17;

import { StudioProV1Storage } from '../StudioProV1Storage.sol';
import { DepositModuleStorage } from '../storages/DepositModuleStorage.sol';
import { ERC20ScaleBoostUpgradeable } from '../ERC20ScaleBoostUpgradeable.sol';
import { ReentrancyGuardUpgradeable } from '@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol';
import { SharesMathLib } from '../libraries/SharesMathLib.sol';
import { SafeERC20 } from '@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol';
import { Math } from '@openzeppelin/contracts/utils/math/Math.sol';
import { IStudioProV1Factory } from '../interfaces/IStudioProV1Factory.sol';
import { IVaultValueV1 } from '../interfaces/IVaultValueV1.sol';
import { IERC20 } from '@openzeppelin/contracts/token/ERC20/IERC20.sol';
import { IERC20Metadata } from '@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol';
import { IERC20Permit } from '@openzeppelin/contracts/token/ERC20/extensions/IERC20Permit.sol';
import { IWETH } from '../interfaces/IWETH.sol';

interface IStudioPro {
    function executeByManager(address[] memory adapters, bytes[] memory params) external;
}

/**
 * @title DepositModule
 * @dev A contract module for handling deposits in a vault-like structure.
 */
contract DepositModule is ReentrancyGuardUpgradeable, ERC20ScaleBoostUpgradeable {
    using SafeERC20 for IERC20;
    using Math for uint256;
    using SharesMathLib for uint256;

    error DEPOSIT__DepositAssetInvalid(address depositAsset);
    error DEPOSIT__InvalidMsgValue(uint256 msgValue, uint256 amount);
    error DEPOSIT__ZeroAmount();
    error DEPOSIT__DepositorNotWhitelisted(address caller);
    error DEPOSIT__AmountLessThanMinimumDepositAmount(uint256 amount);
    error DEPOSIT__NVVExceedCap(uint256 netVaultValue);
    error DEPOSIT__EmptyStrategy();

    event Deposit(address indexed sender, address indexed owner, address depositAsset, uint256 assets, uint256 shares);
    event DepositFeeCharge(
        uint256 amount,
        uint256 protocolRevenueAmount,
        uint256 ownerRevenueAmount,
        address token
    );

    address private immutable nativeWrapper;

    address private constant nativeCoin = 0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE;

    /**
     * @dev Constructor to set the native wrapper address.
     */
    constructor(address _nativeWrapper) {
        nativeWrapper = _nativeWrapper;
    }

    /**
     * @dev Allows a user to deposit assets into the vault.
     * @return shares The number of shares minted for the deposit.
     */
    function deposit(
        address depositAsset,
        uint256 amount,
        address receiver
    ) public payable virtual nonReentrant returns (uint256 shares) {
        if (amount == 0) revert DEPOSIT__ZeroAmount();
        shares = _deposit(depositAsset, msg.sender, receiver, amount);
    }

    function depositAndExecute(
        address depositAsset,
        uint256 amount,
        address receiver
    ) public payable virtual nonReentrant returns (uint256 shares) {
        if (amount == 0) revert DEPOSIT__ZeroAmount();
        shares = _deposit(depositAsset, msg.sender, receiver, amount);
        _executeDepositStrategy();
    }

    /**
     * @dev Allows a user to deposit assets into the vault using a permit.
     * @return shares The number of shares minted for the deposit.
     */
    function depositWithPermit(
        address depositAsset,
        uint256 amount,
        address receiver,
        bytes calldata params
    ) public virtual nonReentrant returns (uint256 shares) {
        if (amount == 0) revert DEPOSIT__ZeroAmount();
        (uint256 deadline, uint8 v, bytes32 r, bytes32 s) = abi.decode(params, (uint256, uint8, bytes32, bytes32));
        IERC20Permit(depositAsset).permit(msg.sender, address(this), amount, deadline, v, r, s);
        shares = _deposit(depositAsset, msg.sender, receiver, amount);
    }

    function depositWithPermitAndExecute(
        address depositAsset,
        uint256 amount,
        address receiver,
        bytes calldata params
    ) public virtual nonReentrant returns (uint256 shares) {
        if (amount == 0) revert DEPOSIT__ZeroAmount();
        (uint256 deadline, uint8 v, bytes32 r, bytes32 s) = abi.decode(params, (uint256, uint8, bytes32, bytes32));
        IERC20Permit(depositAsset).permit(msg.sender, address(this), amount, deadline, v, r, s);
        shares = _deposit(depositAsset, msg.sender, receiver, amount);
        _executeDepositStrategy();
    }

    /**
     * @dev Internal function to handle the deposit logic.
     * @return The number of shares minted for the deposit.
     * @dev This function performs several checks and operations:
     * 1. Validates whitelist if enabled
     * 2. Checks minimum deposit amount if enabled
     * 3. Verifies if the deposit asset is valid
     * 4. Handles native coin deposits by wrapping them (to WETH)
     * 5. Ensures the deposit doesn't exceed the max cap
     * 6. Calculates received shares based on the deposit amount and current vault value
     * 7. Charges deposit fees
     * 8. Records the deposit time for cooldown purposes
     * 9. Mints shares to the receiver
     */
    function _deposit(
        address depositAsset,
        address caller,
        address receiver,
        uint256 amount
    ) internal returns (uint256) {
        DepositModuleStorage.DepositModuleDS storage $deposit = DepositModuleStorage.s();

        // validate whitelist
        if ($deposit.depositWhitelistEnabled) {
            if (!$deposit.depositorWhitelist[caller]) revert DEPOSIT__DepositorNotWhitelisted(caller);
        }

        // validate minimum deposit amount
        if ($deposit.depositMinimumEnabled) {
            if (amount < $deposit.depositMinimum[depositAsset])
                revert DEPOSIT__AmountLessThanMinimumDepositAmount(amount);
        }

        StudioProV1Storage.StudioProV1DS storage $ = StudioProV1Storage.s();

        // check there is native coin on assetsMapping
        if (depositAsset == nativeCoin && !$.depositAssetsMapping[nativeWrapper]) {
            revert DEPOSIT__DepositAssetInvalid(depositAsset);
            // if not native coin then check as usual as ERC20
        } else if (depositAsset != nativeCoin && !$.depositAssetsMapping[depositAsset]) {
            revert DEPOSIT__DepositAssetInvalid(depositAsset);
        }

        // wrap native coin to wrapped ERC20
        bool isNativeCoin;

        if (depositAsset == nativeCoin) {
            isNativeCoin = true;
            if (amount != msg.value) revert DEPOSIT__InvalidMsgValue(msg.value, amount);
            depositAsset = nativeWrapper;
        }

        uint256 depositFeeAmt = _calculateDepositFee($, amount);
        uint256 amountValue = IVaultValueV1(address(this)).getAssetValueByAmount(depositAsset, amount - depositFeeAmt);
        uint256 netVaultValue = IVaultValueV1(address(this)).getNetVaultValue();

        // validate maxCap
        if (amountValue + netVaultValue > $.maxCap) revert DEPOSIT__NVVExceedCap(amountValue + netVaultValue);

        // wrap or transfer
        if (isNativeCoin) {
            IWETH(nativeWrapper).deposit{ value: amount }();
        } else {
            IERC20(depositAsset).safeTransferFrom(caller, address(this), amount);
        }

        // charge deposit fee
        if (depositFeeAmt > 0) _chargeDepositFee($, depositAsset, depositFeeAmt);

        // Use converted amount value for share calculation
        uint256 shares = amountValue.toSharesDown(netVaultValue, totalSupply());

        // record deposit time for cooldown
        $.lastDepositTime[receiver] = block.timestamp;

        _mint(receiver, shares);

        emit Deposit(caller, receiver, depositAsset, amount, shares);

        return shares;
    }

    function _calculateDepositFee(
        StudioProV1Storage.StudioProV1DS storage $,
        uint256 amount
    ) internal view returns (uint256) {
        uint256 depositFee = $.depositFee;
        if (depositFee == 0) return 0;
        (, , uint256 feeScale) = IStudioProV1Factory($.factory).getProtocolFee();
        return amount.mulDiv(depositFee, feeScale);
    }

    function _chargeDepositFee(
        StudioProV1Storage.StudioProV1DS storage $,
        address token,
        uint256 depositFeeAmt
    ) internal returns (uint256) {
        (address protocolFeeRecipient, uint256 protocolFee, uint256 feeScale) = IStudioProV1Factory($.factory)
            .getProtocolFee();
        uint256 protocolRevenueAmt = depositFeeAmt.mulDiv(protocolFee, feeScale);
        uint256 ownerRevenueAmt = depositFeeAmt - protocolRevenueAmt;

        // transfer to protocol fee recipient
        IERC20(token).safeTransfer(protocolFeeRecipient, protocolRevenueAmt);
        // transfer to the vault owner
        IERC20(token).safeTransfer($.feeReceiver, ownerRevenueAmt);

        emit DepositFeeCharge(depositFeeAmt, protocolRevenueAmt, ownerRevenueAmt, token);

        return depositFeeAmt;
    }

    function _executeDepositStrategy() internal {
        StudioProV1Storage.StudioProV1DS storage $ = StudioProV1Storage.s();
        StudioProV1Storage.Strategy storage strategy = $.depositStrategy;

        if (strategy.adapters.length == 0) {
            revert DEPOSIT__EmptyStrategy();
        }

        IStudioPro(address(this)).executeByManager(strategy.adapters, strategy.params);
    }
}

