        StudioProV1Storage.StudioProV1DS storage $ = StudioProV1Storage.s();

        for (uint i = 0; i < $.underlyingDebts.length; i++) {
            address debt = $.underlyingDebts[i];
            uint256 currentDebt = IAccountingV1($.debtAccountings[debt]).getBalance(address(this), debt);
            if (currentDebt > expectedDebtEndStates[i])
                revert WITHDRAW__ExcessDebt(debt, currentDebt, expectedDebtEndStates[i]);
        }
    }

    function _handleWithdrawFeeAndTransfer(
        address receiver,
        uint256[] memory expectedAssetEndStates,
        bool[] memory isWithdraw
    ) internal {
        StudioProV1Storage.StudioProV1DS storage $ = StudioProV1Storage.s();

        uint256 withdrawFee = $.withdrawFee;
        address protocolFeeRecipient;
        uint256 protocolFee;
