            (protocolFeeRecipient, protocolFee, feeScale) = IStudioProV1Factory($.factory).getProtocolFee();
        }

        for (uint i = 0; i < $.underlyingAssets.length; i++) {
            address asset = $.underlyingAssets[i];
            uint256 currentBalance = IAccountingV1($.assetAccountings[asset]).getBalance(address(this), asset);
            if (currentBalance < expectedAssetEndStates[i])
                revert WITHDRAW__InsufficientAssetBalance(asset, currentBalance, expectedAssetEndStates[i]);

            // only withdraw if isWithdraw
            if (!isWithdraw[i]) continue;

            uint256 amount = currentBalance - expectedAssetEndStates[i];

            if (amount > 0) {
                if (withdrawFee > 0) {
                    uint256 withdrawFeeAmt = amount.mulDiv(withdrawFee, feeScale);
                    uint256 protocolAmt = withdrawFeeAmt.mulDiv(protocolFee, feeScale);

                    uint256 netWithdrawAmt = amount - withdrawFeeAmt;

                    // transfer to protocol
