// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.17;

import { StudioProV1Storage } from '../StudioProV1Storage.sol';
import { IStudioProV1Factory } from '../interfaces/IStudioProV1Factory.sol';
import { ERC20Storage as ERC20ModuleStorage } from '../storages/ERC20Storage.sol';
import { DepositModule } from './DepositModule.sol';
import { WithdrawModule } from './WithdrawModule.sol';
import { IERC4626Module } from '../interfaces/IERC4626Module.sol';
import { Math } from '@openzeppelin/contracts/utils/math/Math.sol';
import { SharesMathLib } from '../libraries/SharesMathLib.sol';
import { IVaultValueV1 } from '../interfaces/IVaultValueV1.sol';

contract ERC4626Module is IERC4626Module, DepositModule, WithdrawModule {
    using Math for uint256;
    using SharesMathLib for uint256;

    error ERC4626_NotImplemented();

    enum Rounding {
        Floor,
        Ceil
    }

    constructor(address _nativeWrapper) DepositModule(_nativeWrapper) WithdrawModule(_nativeWrapper) {}

    function asset() public view returns (address) {
        return address(StudioProV1Storage.s().denominator);
    }

    function totalAssets() public view returns (uint256) {
        return IVaultValueV1(address(this)).getNetVaultValue();
    }

    function convertToShares(uint256 assets) public view returns (uint256) {
        return _convertToShares(assets, Rounding.Floor);
    }

    function convertToAssets(uint256 shares) public view returns (uint256) {
        return _convertToAssets(shares, Rounding.Floor);
    }

    function maxDeposit(address) public pure returns (uint256) {
        return type(uint256).max;
    }

    function maxMint(address) public pure returns (uint256) {
        revert ERC4626_NotImplemented();
    }

    function maxWithdraw(address owner) public view returns (uint256) {
        ERC20ModuleStorage.ERC20DS storage $ = ERC20ModuleStorage.s();
        return $._balances[owner].toAssetsDown(IVaultValueV1(address(this)).getNetVaultValue(), $._totalSupply);
    }

    function maxRedeem(address owner) public view returns (uint256) {
        return ERC20ModuleStorage.s()._balances[owner];
    }

    function previewDeposit(uint256 assets) public view returns (uint256) {
        uint256 depositFeeAmt = assets.mulDiv(StudioProV1Storage.s().depositFee, 1e18);
        uint256 netAssets = assets - depositFeeAmt;

        return _convertToShares(netAssets, Rounding.Floor);
    }

    function previewMint(uint256) public pure returns (uint256) {
        revert ERC4626_NotImplemented();
    }

    function previewWithdraw(uint256 assets) public view returns (uint256) {
        uint256 rawAssets = _beforeExitFeeCharge(assets);
        return _convertToShares(rawAssets, Rounding.Ceil);
    }

    function previewRedeem(uint256 shares) public view returns (uint256) {
        uint256 assets = _convertToAssets(shares, Rounding.Floor);
        return assets - _calcExitFee(assets);
    }

    function _totalSupply() internal view returns (uint256) {
        return ERC20ModuleStorage.s()._totalSupply;
    }

    function _balanceOf(address owner) internal view returns (uint256) {
        return ERC20ModuleStorage.s()._balances[owner];
    }

    function _convertToShares(uint256 assets, Rounding rounding) internal view returns (uint256) {
        uint256 assetValue = IVaultValueV1(address(this)).getAssetValueByAmount(asset(), assets);
        uint256 vaultNetValue = IVaultValueV1(address(this)).getNetVaultValue();
        uint256 totalSupply = _totalSupply();

        // Handle first deposit case
        if (totalSupply == 0) {
            return assetValue;
        }

        if (rounding == Rounding.Floor) {
            return assetValue.toSharesDown(vaultNetValue, totalSupply);
        } else {
            return assetValue.toSharesUp(vaultNetValue, totalSupply);
        }
    }

    function _convertToAssets(uint256 shares, Rounding rounding) internal view returns (uint256) {
        uint256 vaultNetValue = IVaultValueV1(address(this)).getNetVaultValue();
        uint256 totalSupply = _totalSupply();

        if (totalSupply == 0) {
            return shares;
        }

        if (rounding == Rounding.Floor) {
            return shares.toAssetsDown(totalSupply, vaultNetValue);
        } else {
            return shares.toAssetsUp(totalSupply, vaultNetValue);
        }
    }

    function _beforeExitFeeCharge(uint256 amount) internal view returns (uint256) {
        StudioProV1Storage.StudioProV1DS storage $ = StudioProV1Storage.s();
        uint256 FEE_SCALE = 1e18;
        return (amount * FEE_SCALE) / (FEE_SCALE - $.withdrawFee);
    }

    function _calcExitFee(uint256 amount) internal view returns (uint256) {
        StudioProV1Storage.StudioProV1DS storage $ = StudioProV1Storage.s();
        uint256 FEE_SCALE = 1e18;
        return amount.mulDiv($.withdrawFee, FEE_SCALE);
    }

    function deposit(uint256 assets, address receiver) public returns (uint256) {
        return DepositModule.deposit(asset(), assets, receiver);
    }

    function mint(uint256, address) public pure returns (uint256) {
        revert ERC4626_NotImplemented();
    }

    function withdraw(uint256 assets, address receiver, address owner) public returns (uint256 shares) {
        shares = previewWithdraw(assets);
        WithdrawModule.withdraw(asset(), shares, receiver, owner);
    }

    function redeem(uint256 shares, address receiver, address owner) public returns (uint256) {
        return WithdrawModule.withdraw(asset(), shares, receiver, owner);
    }
}

