// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.17;

import { StudioProV1Storage } from '../StudioProV1Storage.sol';
import { ERC20ScaleBoostUpgradeable } from '../ERC20ScaleBoostUpgradeable.sol';
import { ReentrancyGuardUpgradeable } from '@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol';
import { SharesMathLib } from '../libraries/SharesMathLib.sol';
import { SafeERC20 } from '@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol';
import { Math } from '@openzeppelin/contracts/utils/math/Math.sol';
import { IERC20 } from '@openzeppelin/contracts/token/ERC20/IERC20.sol';
import { IVaultValueV1 } from '../interfaces/IVaultValueV1.sol';
import { IStudioProV1Factory } from '../interfaces/IStudioProV1Factory.sol';
import { IERC20Metadata } from '@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol';
import { IWETH } from '../interfaces/IWETH.sol';
import { IAccountingV1 } from '../interfaces/IAccountingV1.sol';

contract WithdrawModule is ReentrancyGuardUpgradeable, ERC20ScaleBoostUpgradeable {
    using SafeERC20 for IERC20;
    using Math for uint256;
    using SharesMathLib for uint256;

    event Withdraw(
        address withdrawAsset,
        address sender,
        address receiver,
        address owner,
        uint256 assets,
        uint256 shares
    );

    event WithdrawFeeCharge(
        uint256 amount,
        uint256 protocolRevenueAmount,
        uint256 ownerRevenueAmount,
        address token
    );

    error WITHDRAW__NotValidAdapter(address adapter);
    error WITHDRAW__DelegateCallFailed();
    error WITHDRAW__CoolDownPeriod();
    error WITHDRAW__NotEnoughShare(); // 0x5be4b761
    error WITHDRAW__NotEnoughDenominatorBalance();
    error WITHDRAW__InsufficientAssetBalance(address asset, uint256 currentBalance, uint256 expectedBalance);
    error WITHDRAW__ExcessDebt(address debt, uint256 currentDebt, uint256 expectedDebt);
    error WITHDRAW__WithdrawAssetInvalid(address withdrawAsset);
    error WITHDRAW__ZeroAmount();
    error WITHDRAW__InvalidLength(uint256 expectedLength, uint256 actualLength);
    error WITHDRAW__InvalidIsWithdrawLength(uint256 expectedLength, uint256 actualLength);

    address private immutable nativeWrapper;

    address private constant nativeCoin = 0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE;

    constructor(address _nativeWrapper) {
        nativeWrapper = _nativeWrapper;
    }

    ///////////////////////////////////////////////////////////////////////////////////////////////
    //                                   Basic Withdraw                                          //
    ///////////////////////////////////////////////////////////////////////////////////////////////

    /// @notice Withdraws denominator directly
    /// @return The net amount withdrawn
    function withdraw(
        address withdrawAsset,
        uint256 shares,
        address receiver,
        address owner
    ) public virtual nonReentrant returns (uint256) {
        if (shares > balanceOf(owner) || balanceOf(owner) == 0) revert WITHDRAW__NotEnoughShare();
        if (shares == 0) revert WITHDRAW__ZeroAmount();

        StudioProV1Storage.StudioProV1DS storage $ = StudioProV1Storage.s();

        /// @notice This condition works as follows:
        /// 1. It checks if the current time is less than the last deposit time plus the cooldown period
        /// 2. If true, it means the cooldown period hasn't passed yet
        /// 3. In this case, it reverts the transaction to prevent premature withdrawals
        if (block.timestamp < $.lastDepositTime[owner] + $.cooldownTime) revert WITHDRAW__CoolDownPeriod();
        if (!$.withdrawAssetsMapping[withdrawAsset]) revert WITHDRAW__WithdrawAssetInvalid(withdrawAsset);

        uint256 netWithdrawAmt = _withdraw(withdrawAsset, msg.sender, receiver, owner, shares);

        return netWithdrawAmt;
    }

    /// @notice Internal function to handle the withdrawal process
    /// @return The net amount withdrawn
    function _withdraw(
        address withdrawAsset,
        address caller,
        address receiver,
        address owner,
        uint256 shares
    ) internal returns (uint256) {
        if (caller != owner) {
            _spendAllowance(owner, caller, shares);
        }

        bool isNativeCoin;
        if (withdrawAsset == nativeCoin) {
            isNativeCoin = true;
            withdrawAsset = nativeWrapper;
        }

        uint256 vaultNetValueInAsset = IVaultValueV1(address(this)).getNetVaultValueInAsset(withdrawAsset);

        uint256 withdrawAmount = shares.toAssetsDown(totalSupply(), vaultNetValueInAsset);

        if (withdrawAmount > IERC20(withdrawAsset).balanceOf(address(this)))
            revert WITHDRAW__NotEnoughDenominatorBalance();

        _burn(owner, shares);
        uint256 withdrawFeeAmt = _chargeWithdrawFee(withdrawAsset, withdrawAmount);

        uint256 netWithdrawAmt = withdrawAmount - withdrawFeeAmt;

        if (isNativeCoin) {
            IWETH(nativeWrapper).withdraw(netWithdrawAmt);
            payable(receiver).transfer(netWithdrawAmt);
        } else {
            IERC20(withdrawAsset).safeTransfer(receiver, netWithdrawAmt);
        }

        emit Withdraw(withdrawAsset, caller, receiver, owner, netWithdrawAmt, shares);

        return netWithdrawAmt;
    }

    /// @notice Charges the withdrawal fee
    /// @return The amount of fee charged
    function _chargeWithdrawFee(address token, uint256 amount) internal returns (uint256) {
        StudioProV1Storage.StudioProV1DS storage $ = StudioProV1Storage.s();

        uint256 withdrawFee = $.withdrawFee;

        // skip if withdrawFee is zero
        if (withdrawFee == 0) return 0;

        (address protocolFeeRecipient, uint256 protocolFee, uint256 feeScale) = IStudioProV1Factory($.factory)
            .getProtocolFee();

        uint256 withdrawFeeAmt = amount.mulDiv(withdrawFee, feeScale);
        uint256 protocolRevenueAmt = withdrawFeeAmt.mulDiv(protocolFee, feeScale);
        uint256 ownerRevenueAmt = withdrawFeeAmt - protocolRevenueAmt;

        IERC20(token).safeTransfer(protocolFeeRecipient, protocolRevenueAmt);
        IERC20(token).safeTransfer($.feeReceiver, ownerRevenueAmt);

        emit WithdrawFeeCharge(
            withdrawFeeAmt,
            protocolRevenueAmt,
            ownerRevenueAmt,
            token
        );

        return withdrawFeeAmt;
    }

    ///////////////////////////////////////////////////////////////////////////////////////////////
    //                                    Raw Withdraw                                           //
    ///////////////////////////////////////////////////////////////////////////////////////////////

    /// @notice Performs a raw withdrawal
    /// @dev This function performs a raw withdrawal, which works as follows:
    /// 1. Validates the withdrawal conditions (sufficient shares, non-zero amount, cooldown period)
    /// 2. Calculates the expected end state of assets and debts after withdrawal
    /// 3. Executes a batch of operations using the provided adapters and parameters
    /// 4. Validates that the actual end state matches the expected end state
    /// 5. Burns the withdrawn shares from the owner's balance
    /// 6. Handles the withdrawal fee and transfers the assets to the receiver
    /// @dev as long as the ending balance is meet expected endState so no reverts otherwise it would revert
    function rawWithdraw(
        uint256 shares,
        address receiver,
        address owner,
        address[] calldata adapters,
        bytes[] calldata paramsList,
        bool[] calldata isWithdraw
    ) public virtual nonReentrant {
        if (shares > balanceOf(owner) || balanceOf(owner) == 0) revert WITHDRAW__NotEnoughShare();
        if (shares == 0) revert WITHDRAW__ZeroAmount();
        if (adapters.length != paramsList.length) revert WITHDRAW__InvalidLength(adapters.length, paramsList.length);

        StudioProV1Storage.StudioProV1DS storage $ = StudioProV1Storage.s();

        /// @dev This condition works as follows:
        /// 1. It checks if the current time is less than the last deposit time plus the cooldown period
        /// 2. If true, it means the cooldown period hasn't passed yet
        /// 3. In this case, it reverts the transaction to prevent premature withdrawals
        if (block.timestamp < $.lastDepositTime[owner] + $.cooldownTime) revert WITHDRAW__CoolDownPeriod();

        // [1] Calculate Expected End State
        (uint256[] memory expectedAssetEndStates, uint256[] memory expectedDebtEndStates) = _calcExpectedEndState(
            shares
        );

        if (isWithdraw.length != expectedAssetEndStates.length)
            revert WITHDRAW__InvalidIsWithdrawLength(expectedAssetEndStates.length, isWithdraw.length);

        // [2] Execute Batch
        _executeBatch(adapters, paramsList);

        // [3] Validate End State
        // validate debt balance
        _validateEndState(expectedDebtEndStates);

        if (msg.sender != owner) {
            _spendAllowance(owner, msg.sender, shares);
        }

        _burn(owner, shares);

        // validate asset and transfer
        _handleWithdrawFeeAndTransfer(receiver, expectedAssetEndStates, isWithdraw);
    }

    /// @notice Calculates the expected end state after withdrawal
    /// @return Two arrays representing expected asset and debt end states
    function _calcExpectedEndState(uint256 shares) internal view returns (uint256[] memory, uint256[] memory) {
        StudioProV1Storage.StudioProV1DS storage $ = StudioProV1Storage.s();
        uint256[] memory expectedAssetEndStates = new uint256[]($.underlyingAssets.length);
        uint256[] memory expectedDebtEndStates = new uint256[]($.underlyingDebts.length);

        for (uint i = 0; i < $.underlyingAssets.length; i++) {
            address asset = $.underlyingAssets[i];
            uint256 currentAssetBalance = IAccountingV1($.assetAccountings[asset]).getBalance(address(this), asset);
            uint256 expectedWithdraw = currentAssetBalance.toWithdrawAmountDown(shares, totalSupply());
            expectedAssetEndStates[i] = currentAssetBalance - expectedWithdraw;
        }
        for (uint i = 0; i < $.underlyingDebts.length; i++) {
            address debt = $.underlyingDebts[i];
            uint256 currentDebtBalance = IAccountingV1($.debtAccountings[debt]).getBalance(address(this), debt);
            uint256 expectedRepay = currentDebtBalance.toWithdrawAmountUp(shares, totalSupply());
            expectedDebtEndStates[i] = currentDebtBalance - expectedRepay;
        }

        return (expectedAssetEndStates, expectedDebtEndStates);
    }

    function _executeBatch(address[] calldata adapters, bytes[] calldata paramsList) internal {
        StudioProV1Storage.StudioProV1DS storage $ = StudioProV1Storage.s();

        for (uint i = 0; i < adapters.length; i++) {
            if (!$.withdrawAdapters[adapters[i]]) revert WITHDRAW__NotValidAdapter(adapters[i]);
            (bool success, bytes memory result) = adapters[i].delegatecall(paramsList[i]);

            if (!success) {
                if (result.length < 68) revert WITHDRAW__DelegateCallFailed();
                assembly {
                    result := add(result, 0x04)
                }
                revert(abi.decode(result, (string)));
            }
        }
    }

    function _validateEndState(uint256[] memory expectedDebtEndStates) internal view {
        StudioProV1Storage.StudioProV1DS storage $ = StudioProV1Storage.s();

        for (uint i = 0; i < $.underlyingDebts.length; i++) {
            address debt = $.underlyingDebts[i];
            uint256 currentDebt = IAccountingV1($.debtAccountings[debt]).getBalance(address(this), debt);
            if (currentDebt > expectedDebtEndStates[i])
                revert WITHDRAW__ExcessDebt(debt, currentDebt, expectedDebtEndStates[i]);
        }
    }

    function _handleWithdrawFeeAndTransfer(
        address receiver,
        uint256[] memory expectedAssetEndStates,
        bool[] memory isWithdraw
    ) internal {
        StudioProV1Storage.StudioProV1DS storage $ = StudioProV1Storage.s();

        uint256 withdrawFee = $.withdrawFee;
        address protocolFeeRecipient;
        uint256 protocolFee;
        uint256 feeScale;

        /// @dev This condition works as follows:
        /// 1. It checks if the withdraw fee is greater than zero
        /// 2. If true, it retrieves the protocol fee details for later use in fee calculations
        if (withdrawFee > 0) {
            (protocolFeeRecipient, protocolFee, feeScale) = IStudioProV1Factory($.factory).getProtocolFee();
        }

        for (uint i = 0; i < $.underlyingAssets.length; i++) {
            address asset = $.underlyingAssets[i];
            uint256 currentBalance = IAccountingV1($.assetAccountings[asset]).getBalance(address(this), asset);
            if (currentBalance < expectedAssetEndStates[i])
                revert WITHDRAW__InsufficientAssetBalance(asset, currentBalance, expectedAssetEndStates[i]);

            // only withdraw if isWithdraw
            if (!isWithdraw[i]) continue;

            uint256 amount = currentBalance - expectedAssetEndStates[i];

            if (amount > 0) {
                if (withdrawFee > 0) {
                    uint256 withdrawFeeAmt = amount.mulDiv(withdrawFee, feeScale);
                    uint256 protocolAmt = withdrawFeeAmt.mulDiv(protocolFee, feeScale);

                    uint256 netWithdrawAmt = amount - withdrawFeeAmt;

                    // transfer to protocol
                    IERC20(asset).safeTransfer(protocolFeeRecipient, protocolAmt);
                    // transfer to owner
                    IERC20(asset).safeTransfer($.feeReceiver, withdrawFeeAmt - protocolAmt);
                    // transfer to user
                    IERC20(asset).safeTransfer(receiver, netWithdrawAmt);
                } else {
                    // transfer to user
                    IERC20(asset).safeTransfer(receiver, amount);
                }
            }
        }
    }
}

