// SPDX-License-Identifier: BUSL-1.1

pragma solidity ^0.8.17;

import { StudioProV1Storage } from '../StudioProV1Storage.sol';
import { ERC20ScaleBoostUpgradeable } from '../ERC20ScaleBoostUpgradeable.sol';
import { OwnableUpgradeable } from '@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol';
import { IVaultValueV1 } from '../interfaces/IVaultValueV1.sol';
import { IERC20 } from '@openzeppelin/contracts/token/ERC20/IERC20.sol';

contract FeesModule is ERC20ScaleBoostUpgradeable, OwnableUpgradeable {
    uint256 private constant FEE_SCALE = 1e18;
    uint256 public constant PERF_ASSETS_PER_SHARE_SCALE = 1e26;

    error FEE__FeeScaleExceeded(uint256 fee);
    error FEE__NotManager();

    event PerformanceFeeUpdated(uint256 performanceFeeRate);
    event ManagementFeeUpdated(uint256 managementFeeRate);
    event DepositFeeUpdated(uint256 depositFee);
    event WithdrawFeeUpdated(uint256 withdrawFee);
    event FeeCharged(uint256 performanceFee, uint256 managementFee);

    function _sendFeeToken(address account, uint256 amount) internal virtual {
        _mint(account, amount);
    }

    function setDepositFee(uint256 _depositFee) external virtual onlyOwner {
        if (_depositFee > FEE_SCALE) revert FEE__FeeScaleExceeded(_depositFee);
        StudioProV1Storage.s().depositFee = _depositFee;
        emit DepositFeeUpdated(_depositFee);
    }

    function setWithdrawFee(uint256 _withdrawFee) external virtual onlyOwner {
        if (_withdrawFee > FEE_SCALE) revert FEE__FeeScaleExceeded(_withdrawFee);
        StudioProV1Storage.s().withdrawFee = _withdrawFee;
        emit WithdrawFeeUpdated(_withdrawFee);
    }

    /**
     * @notice Calculates and charges both performance and management fees.
     * @dev This function should be called periodically to accrue fees.
     *
     * Performance Fee Calculation:
     * 1. Calculate current asset per share.
     * 2. If current asset per share > high watermark:
     *    a. Calculate profit: (current asset per share - high watermark) * total shares
     *    b. Calculate performance fee: profit * performance fee rate
     *    c. Update high watermark to current asset per share
     *
     * Management Fee Calculation:
     * 1. Calculate time elapsed since last fee charge.
     * 2. Calculate management fee:
     *    (total assets * management fee rate * time elapsed) / (fee scale * seconds in a year)
     *
     * Both fees are combined and minted as new tokens to the fee receiver.
     * The lastFeeChargeTime is updated after charging fees.
     */
    function chargePerformanceFee() external virtual {
        StudioProV1Storage.StudioProV1DS storage $ = StudioProV1Storage.s();
        // Ensure only managers can call this function
        if (!$.isManager[msg.sender]) revert FEE__NotManager();

        uint256 totalAssets = IVaultValueV1(address(this)).getNetVaultValue();
        uint256 totalShares = IERC20(address(this)).totalSupply();

        // Calculate current asset per share
        // If there are no shares, use the high watermark to avoid division by zero
        uint256 currentAssetPerShare = totalShares > 0
            ? (totalAssets * PERF_ASSETS_PER_SHARE_SCALE) / totalShares
            : $.highWatermark;

        // Calculate and charge performance fee
        uint256 performanceFeeAmt = 0;
        if (currentAssetPerShare > $.highWatermark && $.performanceFee > 0) {
            // Calculate the profit: the increase in asset value per share since the last high watermark
            uint256 profit = ((currentAssetPerShare - $.highWatermark) * totalShares) / PERF_ASSETS_PER_SHARE_SCALE;

            // Calculate the performance fee as a percentage of the profit
            performanceFeeAmt = (profit * $.performanceFee) / FEE_SCALE;

            // Update the high watermark to the current asset per share
            $.highWatermark = currentAssetPerShare;
        }

        // Calculate and charge management fee
        uint256 managementFeeAmt = 0;
        if ($.managementFee > 0) {
            // Calculate the time elapsed since the last fee charge
            uint256 timeDelta = block.timestamp - $.lastFeeChargeTime;

            // Calculate the management fee:
            // (total assets * annual management fee rate * time elapsed) / (fee scale * seconds in a year)
            // This calculates the annual fee for the actual time elapsed
            managementFeeAmt = (totalAssets * $.managementFee * timeDelta) / (FEE_SCALE * 365 days);
        }

        // Combine both fees
        uint256 totalFeeAmt = performanceFeeAmt + managementFeeAmt;

        // If there are fees to charge, mint new tokens to the fee receiver
        if (totalFeeAmt > 0) {
            _sendFeeToken($.feeReceiver, totalFeeAmt);
            // Update the last fee charge time
            $.lastFeeChargeTime = uint64(block.timestamp);
        }

        // Emit an event with the charged fees
        emit FeeCharged(performanceFeeAmt, managementFeeAmt);
    }

    function setPerformanceFee(uint256 _performanceFee) external virtual onlyOwner {
        if (_performanceFee > FEE_SCALE) revert FEE__FeeScaleExceeded(_performanceFee);
        this.chargePerformanceFee();
        StudioProV1Storage.s().performanceFee = _performanceFee;

        emit PerformanceFeeUpdated(_performanceFee);
    }

    function setManagementFee(uint256 _managementFee) external virtual onlyOwner {
        if (_managementFee > FEE_SCALE) revert FEE__FeeScaleExceeded(_managementFee);
        this.chargePerformanceFee();
        StudioProV1Storage.s().managementFee = _managementFee;
        emit ManagementFeeUpdated(_managementFee);
    }

    function setFeeReceiver(address _feeReceiver) external virtual onlyOwner {
        StudioProV1Storage.s().feeReceiver = _feeReceiver;
    }
}

