// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.17;

import { BoostStorage } from '../storages/BoostStorage.sol';
import { ERC20ScaleBoostUpgradeable } from '../ERC20ScaleBoostUpgradeable.sol';
import { ReentrancyGuardUpgradeable } from '@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol';

contract ScaleBoostModule is ReentrancyGuardUpgradeable, ERC20ScaleBoostUpgradeable {
    ///////////////////////////////////////////////////////////////////////////////////////////////
    //                                    Scale                                                  //
    ///////////////////////////////////////////////////////////////////////////////////////////////
    function totalActiveSupply() public view virtual override returns (uint256) {
        return super.totalActiveSupply();
    }

    function activeBalance(address user) public view virtual override returns (uint256) {
        return super.activeBalance(user);
    }

    function getRewardTokens() external view returns (address[] memory) {
        return _getRewardTokens();
    }

    function redeemRewards(address user) external nonReentrant returns (uint256[] memory) {
        return _redeemRewards(user);
    }

    function redeemRewardsAndGetReward(address user) external nonReentrant {
        _redeemBoostRewardAll(user);
        _redeemRewards(user);
    }

    ///////////////////////////////////////////////////////////////////////////////////////////////
    //                                      Boost                                                //
    ///////////////////////////////////////////////////////////////////////////////////////////////

    function rewardDuration() external view returns (uint256) {
        return _rewardDuration();
    }

    function userRewardPerTokenPaid(address _user, address _rewardsToken) external view returns (uint256) {
        return _userRewardPerTokenPaid(_user, _rewardsToken);
    }

    function rewardData(address _rewardsToken) external view returns (BoostStorage.Reward memory) {
        return _rewardData(_rewardsToken);
    }

    function lastTimeRewardApplicable(address _rewardsToken) external view returns (uint256) {
        return _lastTimeRewardApplicable(_rewardsToken);
    }

    function rewardPerToken(address _rewardsToken) external view returns (uint256) {
        return _rewardPerToken(_rewardsToken);
    }

    function getAllRewardTokens() external view returns (address[] memory) {
        return _getAllRewardTokens();
    }

    function getRewardTokensCount() external view returns (uint256) {
        return _getRewardTokensCount();
    }

    function earned(address account, address _rewardsToken) external view returns (uint256) {
        return _earned(account, _rewardsToken);
    }

    function getRewardForDuration(address _rewardsToken) external view returns (uint256) {
        return _getRewardForDuration(_rewardsToken);
    }

    function boostMinAmount(address _rewardsToken) external view returns (uint256) {
        return BoostStorage.s().minAmount[_rewardsToken];
    }

    function redeemBoostReward(address user, address[] calldata rewardTokens) external nonReentrant {
        _redeemBoostReward(user, rewardTokens);
    }

    function redeemBoostRewardAll(address user) external nonReentrant {
        _redeemBoostRewardAll(user);
    }

    function notifyRewardAmount(address _rewardsToken, uint256 reward) external nonReentrant {
        _notifyRewardAmount(_rewardsToken, reward);
    }
}

