contracts/studio/prov1/StudioProV1Storag.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.17;

import '@openzeppelin/contracts/token/ERC20/IERC20.sol';

library StudioProV1Storage {
    struct SelectorAdapter {
        bool isActive;
        address adapter;
    }

    struct Strategy {
        address[] adapters;
        bytes[] params;
    }

    struct StudioProV1DS {
        // Vault configuration
        address factory;
        bool upgradeable;
        uint256 upgradeTimelock;
        uint256 cooldownTime;
        IERC20 denominator;
        address denominatorAccounting;
        // Assets and debts
        address[] underlyingAssets;
        address[] underlyingDebts;
        mapping(address => bool) depositAssetsMapping;
        mapping(address => bool) underlyingAssetsMapping;
        mapping(address => bool) underlyingDebtsMapping;
        // accounting
        mapping(address => address) assetAccountings;
        mapping(address => address) debtAccountings;
        // Managers and adapters
        mapping(address => bool) isManager;
        mapping(address => bool) withdrawAssetsMapping;
        mapping(address => bool) managerAdapters;
        mapping(address => bool) ownerAdapters;
        mapping(address => bool) withdrawAdapters;
        // roles
        address riskManager;
        // Function selectors and adapters
        mapping(bytes4 => SelectorAdapter) funcSelectors;
        // fees
        uint256 depositFee;
        uint256 withdrawFee;
        uint256 performanceFee;
        uint256 managementFee;
        uint256 highWatermark;
        uint256 lastFeeChargeTime;
        address feeReceiver;
        // User data
        mapping(address => uint256) lastDepositTime;
        // upgrades
        address proposedVaultImplementation;
        uint256 proposedVaultUpgradeTime;
        // Price deviation tracking
        uint256 dailyPriceDeviationBps;
        uint256 lastPriceDeviationResetTime;
        uint256 cumulativePriceDeviationAllowanceBps;
        // cap
        uint256 maxCap;
        uint256 maxDebtRatio;
        // simulation
        bool isSimulation;
        // wrapper
        mapping(uint256 => address) nftToWrapper;
        mapping(address => uint256) wrapperToNft;
        // strategy
        Strategy depositStrategy;
        mapping(uint256 => Strategy) publicStrategies;
    }

    // keccak256(abi.encode(uint256(keccak256("factordao.studio.pro.vault")) - 1)) & bytes32(uint256(0xff))
    bytes32 private constant STORAGE_SLOT = 0xeb5bb3420d9366368c64688d6df836957f2c655b917ed6671c4a93199009bc00;

    function s() internal pure returns (StudioProV1DS storage ds) {
        bytes32 slot = STORAGE_SLOT;
        assembly {
            ds.slot := slot
        }
    }
}

contracts/studio/prov1/interfaces/IAccou.content:
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.17;

interface IAccountingV1 {
    function getBalance(address vault, address asset) external view returns (uint256);
    function getPriceUSD(address asset) external view returns (uint256);
    function getUSDDecimals(address asset) external view returns (uint256);
    function getDecimals(address asset) external view returns (uint256);
    function getPriceDetails(address asset)
        external
        view
        returns (uint256 price, uint256 decimalsUSD, uint256 decimals);
    function getBalanceAndPriceDetails(address vault, address asset)
        external
        view
        returns (uint256 balance, uint256 decimals, uint256 priceUSD, uint256 decimalsUSD);
    function isTransferable(address asset) external view returns (bool);

    function getUnderlyingToken(address vault, address asset) external view returns (address);

    function tokenType() external pure returns (uint8);
    function description() external pure returns (string memory);
}

contracts/studio/prov1/modules/VaultValu.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.17;

import {StudioProV1Storage} from "../StudioProV1Storage.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {IAccountingV1} from "../interfaces/IAccountingV1.sol";
import {IERC20Metadata as IERC20} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";

contract VaultValueModule {
    using Math for uint256;

    error VAULT_VALUE__AssetNotFound(address asset);

    struct PriceData {
        uint256 priceInUSD;
        uint256 priceInUSDDecimals;
        uint256 tokenDecimals;
    }

    /// @notice Calculates the total asset and debt value of the vault
    /// @return totalAsset The total value of assets in the vault
    /// @return totalDebt The total value of debts in the vault
    function getAssetDebtValue() public view virtual returns (uint256 totalAsset, uint256 totalDebt) {
        PriceData memory denominatorData = _getDenominatorPrice();
        return _calcVaultValue(
            denominatorData, StudioProV1Storage.s().underlyingAssets, StudioProV1Storage.s().underlyingDebts
        );
    }

    /// @notice Calculates the net value of the vault
    /// @return The net value of the vault (total assets minus total debts)
    function getNetVaultValue() public view virtual returns (uint256) {
        (uint256 totalAsset, uint256 totalDebt) = getAssetDebtValue();
        return totalAsset - totalDebt;
    }

    /// @notice Calculates the net value of the vault in terms of a specific asset
    /// @return The net value of the vault in the specified asset
    function getNetVaultValueInAsset(address _asset) public view virtual returns (uint256) {
        PriceData memory assetData = _getPrice(_asset);

        (uint256 totalAsset, uint256 totalDebt) =
            _calcVaultValue(assetData, StudioProV1Storage.s().underlyingAssets, StudioProV1Storage.s().underlyingDebts);

        return totalAsset - totalDebt;
    }

    /// @notice Calculates the total asset and debt value of the vault in terms of a specific asset
    /// @return The total asset value in the specified asset
    /// @return The total debt value in the specified asset
    function getAssetDebtValueInAsset(address _asset) public view virtual returns (uint256, uint256) {
        PriceData memory assetData = _getPrice(_asset);

        (uint256 totalAsset, uint256 totalDebt) =
            _calcVaultValue(assetData, StudioProV1Storage.s().underlyingAssets, StudioProV1Storage.s().underlyingDebts);

        return (totalAsset, totalDebt);
    }

    /// @notice Calculates the value of a given amount of an asset in terms of the denominator asset
    /// @param asset The address of the asset to calculate the value for
    /// @param amount The amount of the asset to calculate the value for
    /// @return The value of the specified amount of the asset in terms of the denominator asset
    function getAssetValueByAmount(address asset, uint256 amount) public view virtual returns (uint256) {
        PriceData memory assetData = _getPrice(asset);
        PriceData memory denominatorData = _getDenominatorPrice();
        return _convertPrice(amount, assetData, denominatorData);
    }

    /// @notice Calculates the total value of all assets in the vault
    /// @return The total value of all assets in the vault
    function getTotalAssetValue() public view virtual returns (uint256) {
        PriceData memory denominatorData = _getDenominatorPrice();
        return _calcTotalAssetValue(
            StudioProV1Storage.s().underlyingAssets,
            denominatorData.priceInUSD,
            denominatorData.priceInUSDDecimals,
            denominatorData.tokenDecimals
        );
    }

    /// @notice Calculates the total value of all debts in the vault
    /// @return The total value of all debts in the vault
    function getTotalDebtValue() public view virtual returns (uint256) {
        PriceData memory denominatorData = _getDenominatorPrice();
        return _calcTotalDebtValue(
            StudioProV1Storage.s().underlyingDebts,
            denominatorData.priceInUSD,
            denominatorData.priceInUSDDecimals,
            denominatorData.tokenDecimals
        );
    }

    ///////////////////////////////////////////////////////////////////////////////////////////////
    //                                      Internals                                            //
    ///////////////////////////////////////////////////////////////////////////////////////////////

    /// @notice Calculates the total asset and debt value of the vault
    /// @param quotePriceData The price data of the quote asset
    /// @param assets The array of asset addresses
    /// @param debts The array of debt addresses
    /// @return totalAsset The total value of assets in the vault
    /// @return totalDebt The total value of debts in the vault
    function _calcVaultValue(PriceData memory quotePriceData, address[] memory assets, address[] memory debts)
        internal
        view
        virtual
        returns (uint256 totalAsset, uint256 totalDebt)
    {
        // which is longer? asset or debt? . This is for gas optimization
        uint256 length = assets.length > debts.length ? assets.length : debts.length;
        for (uint256 i = 0; i < length; i++) {
            if (i < assets.length) totalAsset += _calcAssetValue(assets[i], quotePriceData);
            if (i < debts.length) totalDebt += _calcDebtValue(debts[i], quotePriceData);
        }
    }

    /// @notice Calculates the value of an asset
    /// @param asset The address of the asset
    /// @param denominatorData The price data of the denominator asset
    /// @return The value of the asset in terms of the denominator
    function _calcAssetValue(address asset, PriceData memory denominatorData) internal view virtual returns (uint256) {
        address assetAccounting = _getAssetAcct(asset);
        uint256 assetBalance = IAccountingV1(assetAccounting).getBalance(address(this), asset);

        // @dev This condition works as follows:
        // 1. If the asset balance is zero, there's no need to perform further calculations
        // 2. It helps to avoid unnecessary computations and potential division by zero errors
        // 3. Returns zero immediately if the balance is zero, optimizing gas usage
        if (assetBalance == 0) return 0;

        PriceData memory assetData = _getPriceFromAcct(assetAccounting, asset);
        return _convertPrice(assetBalance, assetData, denominatorData);
    }

    /// @notice Calculates the value of a debt
    /// @param debt The address of the debt
    /// @param denominatorData The price data of the denominator asset
    /// @return The value of the debt in terms of the denominator
    function _calcDebtValue(address debt, PriceData memory denominatorData) internal view virtual returns (uint256) {
        address debtAccounting = _getDebtAcct(debt);
        uint256 debtBalance = IAccountingV1(debtAccounting).getBalance(address(this), debt);
        // @notice This condition works as follows:
        // 1. If the debt balance is zero, there's no need to perform further calculations
        // 2. It helps to avoid unnecessary computations and potential division by zero errors
        // 3. Returns zero immediately if the balance is zero, optimizing gas usage
        if (debtBalance == 0) return 0;
        PriceData memory debtData = _getPriceFromAcct(debtAccounting, debt);
        return _convertPrice(debtBalance, debtData, denominatorData);
    }

    /**
     * @notice Converts an amount from one asset to another using their respective USD prices
     * @dev This function optimizes precision by:
     * 1. Combining multiplications before division to minimize precision loss
     * 2. Using mulDiv for safe arithmetic operations with rounding control
     * 3. Maintaining consistent decimal handling throughout the calculation
     * @param amount The amount of the base asset to convert
     * @param basePriceData Price data for the asset being converted from
     * @param quotePriceData Price data for the asset being converted to
     * @return The equivalent amount in the quote asset, rounded down to maintain precision
     */
    function _convertPrice(uint256 amount, PriceData memory basePriceData, PriceData memory quotePriceData)
        internal
        view
        virtual
        returns (uint256)
    {
        // 1. Convert amount to USD (maintaining precision)
        uint256 amountInUSD =
            amount.mulDiv(basePriceData.priceInUSD, 10 ** basePriceData.tokenDecimals, Math.Rounding.Floor);

        // 2. Convert USD amount to quote token
        // Need to adjust for decimal differences between USD price decimals
        if (basePriceData.priceInUSDDecimals > quotePriceData.priceInUSDDecimals) {
            amountInUSD = amountInUSD.mulDiv(
                1, 10 ** (basePriceData.priceInUSDDecimals - quotePriceData.priceInUSDDecimals), Math.Rounding.Floor
            );
        } else if (quotePriceData.priceInUSDDecimals > basePriceData.priceInUSDDecimals) {
            amountInUSD = amountInUSD.mulDiv(
                10 ** (quotePriceData.priceInUSDDecimals - basePriceData.priceInUSDDecimals), 1, Math.Rounding.Floor
            );
        }

        // 3. Convert USD value to quote token
        return amountInUSD.mulDiv(10 ** quotePriceData.tokenDecimals, quotePriceData.priceInUSD, Math.Rounding.Floor);
    }

    /// @notice Calculates the total value of a list of assets or debts
    /// @param assets The array of asset or debt addresses
    /// @param priceInUSD The price of the denominator asset in USD
    /// @param priceInUSDDecimals The number of decimals for the price in USD
    /// @param tokenDecimals The number of decimals for the token
    /// @return totalValue The total value of the assets or debts
    function _calcTotalAssetValue(
        address[] memory assets,
        uint256 priceInUSD,
        uint256 priceInUSDDecimals,
        uint256 tokenDecimals
    ) internal view virtual returns (uint256 totalValue) {
        PriceData memory denominatorData = PriceData(priceInUSD, priceInUSDDecimals, tokenDecimals);
        for (uint256 i = 0; i < assets.length; i++) {
            totalValue += _calcAssetValue(assets[i], denominatorData);
        }
    }

    /// @notice Calculates the total value of a list of debts
    /// @param debts The array of debt addresses
    /// @param priceInUSD The price of the denominator asset in USD
    /// @param priceInUSDDecimals The number of decimals for the price in USD
    /// @param tokenDecimals The number of decimals for the token
    /// @return totalValue The total value of the debts
    function _calcTotalDebtValue(
        address[] memory debts,
        uint256 priceInUSD,
        uint256 priceInUSDDecimals,
        uint256 tokenDecimals
    ) internal view virtual returns (uint256 totalValue) {
        PriceData memory denominatorData = PriceData(priceInUSD, priceInUSDDecimals, tokenDecimals);
        for (uint256 i = 0; i < debts.length; i++) {
            totalValue += _calcDebtValue(debts[i], denominatorData);
        }
    }

    /// @notice Retrieves the accounting contract address for an asset
    /// @param asset The address of the asset
    /// @return The accounting contract address for the asset
    function _getAssetAcct(address asset) internal view virtual returns (address) {
        return StudioProV1Storage.s().assetAccountings[asset];
    }

    /// @notice Retrieves the accounting contract address for a debt
    /// @param debt The address of the debt
    /// @return The accounting contract address for the debt
    function _getDebtAcct(address debt) internal view virtual returns (address) {
        return StudioProV1Storage.s().debtAccountings[debt];
    }

    /// @notice Retrieves the price data for an asset
    /// @param asset The address of the asset
    /// @return A PriceData struct containing the price information for the asset
    function _getPrice(address asset) internal view virtual returns (PriceData memory) {
        StudioProV1Storage.StudioProV1DS storage $ = StudioProV1Storage.s();
        if (!$.underlyingAssetsMapping[asset]) revert VAULT_VALUE__AssetNotFound(asset);
        address assetAccounting = $.assetAccountings[asset];
        return _getPriceFromAcct(assetAccounting, asset);
    }

    /// @notice Retrieves the price data for the denominator asset
    /// @return A PriceData struct containing the price information for the denominator asset
    function _getDenominatorPrice() internal view virtual returns (PriceData memory) {
        StudioProV1Storage.StudioProV1DS storage $ = StudioProV1Storage.s();
        address denominatorAddress = address($.denominator);
        return _getPriceFromAcct($.denominatorAccounting, denominatorAddress);
    }

    /// @notice Retrieves the price data for an asset from its accounting contract
    /// @param assetAccounting The address of the asset's accounting contract
    /// @param asset The address of the asset
    /// @return A PriceData struct containing the price information for the asset
    function _getPriceFromAcct(address assetAccounting, address asset)
        internal
        view
        virtual
        returns (PriceData memory)
    {
        (uint256 priceInUSD, uint256 priceInUSDDecimals, uint256 tokenDecimals) =
            IAccountingV1(assetAccounting).getPriceDetails(asset);

        return PriceData(priceInUSD, priceInUSDDecimals, tokenDecimals);
    }

    function getNetVaultValueInUSD() external view returns (uint256 netVaultValueInUSD) {
        address[] memory assets = StudioProV1Storage.s().underlyingAssets;
        address[] memory debts = StudioProV1Storage.s().underlyingDebts;
        for (uint256 i = 0; i < assets.length; i++) {
            address assetAccounting = _getAssetAcct(assets[i]);
            uint256 assetBalance = IAccountingV1(assetAccounting).getBalance(address(this), assets[i]);
            if (assetBalance == 0) return 0;
            PriceData memory assetData = _getPriceFromAcct(assetAccounting, assets[i]);

            uint256 assetValue =
                assetBalance.mulDiv(assetData.priceInUSD, 10 ** assetData.tokenDecimals, Math.Rounding.Floor);
            netVaultValueInUSD += assetValue;
        }
        for (uint256 i = 0; i < debts.length; i++) {
            address debtAccounting = _getDebtAcct(debts[i]);
            uint256 debtBalance = IAccountingV1(debtAccounting).getBalance(address(this), debts[i]);
            if (debtBalance == 0) return 0;
            PriceData memory debtData = _getPriceFromAcct(debtAccounting, debts[i]);
            uint256 debtValue =
                debtBalance.mulDiv(debtData.priceInUSD, 10 ** debtData.tokenDecimals, Math.Rounding.Floor);
            netVaultValueInUSD -= debtValue;
        }
    }
}
